4.6 Joins

# Left join: keep all rows from the left table
flights |&gt;
  left_join(airlines, by = "carrier") |&gt;
  rename(airline_name = name) |&gt;
  left_join(airports, by = c("dest" = "faa")) |&gt;
  rename(airport_name = name)

# Common join types
inner_join(x, y, by = "id")  # only matching rows in both
left_join(x, y, by = "id")   # all rows from x
right_join(x, y, by = "id")  # all rows from y
full_join(x, y, by = "id")   # all rows from both
anti_join(x, y, by = "id")   # rows in x not in y

4.8 Practical example: babynames

library(babynames)

# Trend for a single name
babynames |&gt;
  filter(name == "Sophie") |&gt;
  ggplot(aes(x = year, y = n, color = sex)) +
  geom_line()

# Year-normalised proportions and change over time
babynames |&gt;
  group_by(year) |&gt;
  mutate(year_total = sum(n)) |&gt;
  ungroup() |&gt;
  mutate(fraction = n / year_total) |&gt;
  group_by(name) |&gt;
  arrange(name, year) |&gt;
  mutate(ratio = fraction / lag(fraction)) |&gt;     # year-on-year growth
  filter(fraction &gt;= 0.00001) |&gt;
  slice_max(ratio, n = 1)

5.2 Memory and vector allocation
Growing a vector inside a loop is one of the most common performance mistakes in R. Each iteration copies the entire vector to a new, larger block of memory.

n &lt;- 10000

# BAD — grows on each iteration
growing &lt;- function(n) {
  x &lt;- NULL
  for (i in seq_len(n)) x &lt;- c(x, rnorm(1))
  x
}

# GOOD — pre-allocate, then fill
pre_allocate &lt;- function(n) {
  x &lt;- numeric(n)
  for (i in seq_len(n)) x[i] &lt;- rnorm(1)
  x
}

# BEST — use a vectorised function directly
vectorised &lt;- function(n) rnorm(n)

microbenchmark(
  growing     = growing(n),
  pre_alloc   = pre_allocate(n),
  vectorised  = vectorised(n),
  times = 5
)

