13.7 The tidymodels framework
tidymodels is the tidyverse successor to caret. It separates preprocessing (recipes), model specification, and fitting into distinct, composable steps.

library(tidymodels)

# 1. Preprocessing recipe
rec &lt;- recipe(outcome ~ ., data = train_dat) |&gt;
  step_impute_median(all_numeric_predictors()) |&gt;
  step_normalize(all_numeric_predictors()) |&gt;
  step_dummy(all_nominal_predictors())

# 2. Model specification
lr_spec &lt;- logistic_reg(penalty = tune(), mixture = 1) |&gt;
  set_engine("glmnet") |&gt;
  set_mode("classification")

# 3. Workflow
wf &lt;- workflow() |&gt;
  add_recipe(rec) |&gt;
  add_model(lr_spec)

# 4. Tune with cross-validation
cv_folds &lt;- vfold_cv(train_dat, v = 10)
tune_res  &lt;- tune_grid(wf, resamples = cv_folds, grid = 20)

# 5. Finalise and fit
best_params &lt;- select_best(tune_res, metric = "roc_auc")
final_fit   &lt;- finalize_workflow(wf, best_params) |&gt; fit(train_dat)

# 6. Evaluate on test set
final_fit |&gt;
  augment(test_dat) |&gt;
  roc_auc(outcome, .pred_Yes)

14.4 Server logic

server &lt;- function(input, output, session) {

  # Render a plot that depends on the input
  output$survival_plot &lt;- renderPlot({
    df_filtered &lt;- patients |&gt;
      filter(group == input$group, age &lt;= input$age)

    ggplot(df_filtered, aes(x = time, y = survival)) +
      geom_line() +
      labs(title = paste("Group:", input$group))
  })

  # Render a summary table
  output$summary_table &lt;- renderTable({
    patients |&gt;
      filter(group == input$group) |&gt;
      summarise(n = n(), median_los = median(los))
  })

}

14.5 Reactive programming
Shiny uses reactive expressions to avoid unnecessary recomputation. A reactive expression caches its value and only re-runs when its inputs change.

server &lt;- function(input, output, session) {

  # Reactive expression: filtered data (recomputes only when input$group changes)
  filtered_data &lt;- reactive({
    patients |&gt; filter(group == input$group)
  })

  # Multiple outputs can share the same reactive expression
  output$plot  &lt;- renderPlot({ ggplot(filtered_data(), ...) })
  output$table &lt;- renderTable({ filtered_data() })

}


14.5.1 observeEvent() — respond to button clicks

observeEvent(input$run_analysis, {
  # This block runs only when the button is clicked
  output$result &lt;- renderText(paste("Analysis run with n =", input$n))
})

14.7 Complete working example

library(shiny)
library(babynames)
library(ggplot2)

ui &lt;- fluidPage(
  titlePanel("Baby Name Explorer"),
  sidebarLayout(
    sidebarPanel(
      textInput("name", "Enter a name:", value = "Emma")
    ),
    mainPanel(
      plotOutput("trend", height = "400px")
    )
  )
)

server &lt;- function(input, output, session) {
  output$trend &lt;- renderPlot({
    babynames |&gt;
      filter(name == input$name) |&gt;
      ggplot(aes(x = year, y = prop, color = sex)) +
      geom_line(linewidth = 1) +
      labs(
        title = paste("Popularity of", input$name, "over time"),
        x = "Year", y = "Proportion of births"
      ) +
      theme_minimal()
  })
}

shinyApp(ui = ui, server = server)
